typedef BOOL (WINAPI *flush_function)(HANDLE);
typedef struct flush_record {
 DWORD tid,error,path_error,storage_error,io_error; BOOL ok;
 LONGLONG begin,end,metadata_end;cpu_snapshot before,after;
 IO_COUNTERS io_before,io_after;FILE_STORAGE_INFO storage;
 wchar_t path[512];LONG complete;
} flush_record;
static flush_record flush_records[256];
static LONG flush_count,active_calls;
static flush_function original_flush;
static void **flush_slot;
static ULONG slot_rva;
static BOOL WINAPI traced_flush(HANDLE file){
 DWORD incoming=GetLastError();InterlockedIncrement(&active_calls);
 LONG index=InterlockedIncrement(&flush_count)-1;
 flush_record scratch={0},*r=index>=0 && index<256?&flush_records[index]:&scratch;
 r->tid=GetCurrentThreadId();r->before=cpu_read();
 if(!GetProcessIoCounters(GetCurrentProcess(),&r->io_before))r->io_error=GetLastError();
 SetLastError(incoming);r->begin=tick();BOOL result=original_flush(file);
 DWORD outgoing=GetLastError();r->end=tick();r->error=result?0:outgoing;r->ok=result;
 r->after=cpu_read();
 if(!GetProcessIoCounters(GetCurrentProcess(),&r->io_after) && !r->io_error)r->io_error=GetLastError();
 DWORD length=GetFinalPathNameByHandleW(file,r->path,512,FILE_NAME_NORMALIZED);
 if(!length || length>=512){r->path_error=length?ERROR_INSUFFICIENT_BUFFER:GetLastError();r->path[0]=0;}
 if(!GetFileInformationByHandleEx(file,FileStorageInfo,&r->storage,sizeof(r->storage)))r->storage_error=GetLastError();
 r->metadata_end=tick();InterlockedExchange(&r->complete,1);
 InterlockedDecrement(&active_calls);SetLastError(outgoing);return result;
}
static int within(ULONG rva,size_t size,ULONG image){return rva<image && size<=image-rva;}
static int find_flush_slot(HMODULE module){
 BYTE *base=(BYTE *)module;IMAGE_DOS_HEADER *dos=(IMAGE_DOS_HEADER *)base;
 if(dos->e_magic!=IMAGE_DOS_SIGNATURE || dos->e_lfanew<=0 || dos->e_lfanew>1048576)return 0;
 IMAGE_NT_HEADERS64 *nt=(IMAGE_NT_HEADERS64 *)(base+dos->e_lfanew);
 if(nt->Signature!=IMAGE_NT_SIGNATURE || nt->OptionalHeader.Magic!=IMAGE_NT_OPTIONAL_HDR64_MAGIC)return 0;
 ULONG image=nt->OptionalHeader.SizeOfImage;
 IMAGE_DATA_DIRECTORY imports=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];
 if(!within(imports.VirtualAddress,imports.Size,image) || imports.Size<sizeof(IMAGE_IMPORT_DESCRIPTOR))return 0;
 IMAGE_IMPORT_DESCRIPTOR *descs=(IMAGE_IMPORT_DESCRIPTOR *)(base+imports.VirtualAddress);
 unsigned matches=0;
 for(size_t j=0;j<imports.Size/sizeof(*descs) && descs[j].Name;++j){
  IMAGE_IMPORT_DESCRIPTOR d=descs[j];
  if(!d.OriginalFirstThunk || !d.FirstThunk)continue;
  for(ULONG i=0;i<image/sizeof(IMAGE_THUNK_DATA64);++i){
   size_t offset=(size_t)i*sizeof(IMAGE_THUNK_DATA64);
   if(offset>ULONG_MAX || !within(d.OriginalFirstThunk,(size_t)offset+sizeof(IMAGE_THUNK_DATA64),image) ||
      !within(d.FirstThunk,(size_t)offset+sizeof(IMAGE_THUNK_DATA64),image))return 0;
   IMAGE_THUNK_DATA64 *name=(IMAGE_THUNK_DATA64 *)(base+d.OriginalFirstThunk+offset);
   if(!name->u1.AddressOfData)break;
   if(IMAGE_SNAP_BY_ORDINAL64(name->u1.Ordinal))continue;
   if(name->u1.AddressOfData>ULONG_MAX || !within((ULONG)name->u1.AddressOfData,sizeof(IMAGE_IMPORT_BY_NAME)+32,image))return 0;
   IMAGE_IMPORT_BY_NAME *entry=(IMAGE_IMPORT_BY_NAME *)(base+(ULONG)name->u1.AddressOfData);
   if(memcmp(entry->Name,"FlushFileBuffers",sizeof("FlushFileBuffers")))continue;
   flush_slot=(void **)(base+d.FirstThunk+offset);slot_rva=(ULONG)((BYTE *)flush_slot-base);++matches;
  }
 }
 void *kernel32=(void *)GetProcAddress(GetModuleHandleW(L"kernel32.dll"),"FlushFileBuffers");
 void *kernelbase=(void *)GetProcAddress(GetModuleHandleW(L"kernelbase.dll"),"FlushFileBuffers");
 fprintf(stderr,"FLUSH_SLOT matches=%u target=%p kernel32=%p kernelbase=%p\n",matches,flush_slot?*flush_slot:NULL,kernel32,kernelbase);
 return matches==1 && flush_slot && (*flush_slot==kernel32 || *flush_slot==kernelbase);
}
static int exchange_slot(void *expected,void *replacement){
 DWORD previous=0,unused=0;if(!VirtualProtect(flush_slot,sizeof(void *),PAGE_READWRITE,&previous))return 0;
 void *value=InterlockedCompareExchangePointer((void *volatile *)flush_slot,replacement,expected);
 BOOL restored=VirtualProtect(flush_slot,sizeof(void *),previous,&unused);
 return value==expected && restored;
}
static void json_path(const wchar_t *path){
 char utf8[2048];if(!WideCharToMultiByte(CP_UTF8,0,path,-1,utf8,sizeof(utf8),NULL,NULL))utf8[0]=0;
 fputc('"',stderr);for(const unsigned char *p=(unsigned char *)utf8;*p;++p){
  if(*p=='"'||*p=='\\')fprintf(stderr,"\\%c",*p);else if(*p<32)fprintf(stderr,"\\u%04x",*p);else fputc(*p,stderr);
 }fputc('"',stderr);
}
static int trace_run(int argc,char **argv){
 const GUID provider={0x2d4ebca6,0xea64,0x453f,{0xa2,0x92,0xae,0x2e,0xa0,0xee,0x51,0x3b}};
 const GUID session={0xc77a298c,0x2587,0x4511,{0x9b,0xb6,0x45,0x2c,0x81,0x99,0x7e,0xa1}};
 struct properties {EVENT_TRACE_PROPERTIES value;wchar_t name[128],file[32768];} *properties=calloc(1,sizeof(*properties));
 if(!properties)return 2;
 DWORD n=GetEnvironmentVariableW(L"NEXAUI_R01_PRIVATE_TRACE_FILE",properties->file,32768);
 if(!n || n>=32768 || GetFileAttributesW(properties->file)!=INVALID_FILE_ATTRIBUTES){free(properties);return 3;}
 wcscpy_s(properties->name,128,L"NexaUI R01 owned cache-flush timing");
 EVENT_TRACE_PROPERTIES *p=&properties->value;
 p->Wnode.BufferSize=sizeof(*properties);p->Wnode.Guid=session;p->Wnode.ClientContext=1;p->Wnode.Flags=WNODE_FLAG_TRACED_GUID;
 p->BufferSize=64;p->MinimumBuffers=2;p->MaximumBuffers=8;p->MaximumFileSize=16;
 p->LogFileMode=EVENT_TRACE_FILE_MODE_SEQUENTIAL|EVENT_TRACE_PRIVATE_LOGGER_MODE|EVENT_TRACE_PRIVATE_IN_PROC;
 p->LoggerNameOffset=offsetof(struct properties,name);p->LogFileNameOffset=offsetof(struct properties,file);
 TRACEHANDLE trace=0;ULONG start=StartTraceW(&trace,properties->name,p);
 if(start){fprintf(stderr,"ETW {\"start\":%lu}\n",start);free(properties);return 4;}
 ULONG enable=EnableTraceEx2(trace,&provider,EVENT_CONTROL_CODE_ENABLE_PROVIDER,TRACE_LEVEL_VERBOSE,UINT64_C(0x800000000000000f),0,0,NULL);
 int result=enable?5:original_probe_main(argc,argv);
 ULONG disable=EnableTraceEx2(trace,&provider,EVENT_CONTROL_CODE_DISABLE_PROVIDER,0,0,0,0,NULL);
 ULONG stop=ControlTraceW(trace,properties->name,p,EVENT_TRACE_CONTROL_STOP);
 fprintf(stderr,"ETW {\"start\":%lu,\"enable\":%lu,\"disable\":%lu,\"stop\":%lu,\"events_lost\":%lu,\"buffers_written\":%lu,\"log_buffers_lost\":%lu}\n",start,enable,disable,stop,p->EventsLost,p->BuffersWritten,p->LogBuffersLost);
 free(properties);return result||disable||stop?6:0;
}
int main(int argc,char **argv){
 QueryPerformanceFrequency(&probe_frequency);
 HMODULE cache=LoadLibraryExW(L"D3DSCache.dll",NULL,LOAD_LIBRARY_SEARCH_SYSTEM32);
 if(!cache || !find_flush_slot(cache)){fprintf(stderr,"FLUSH_SETUP_FAILED %lu\n",GetLastError());return 10;}
 original_flush=(flush_function)*flush_slot;
 SetLastError(789);BOOL direct=original_flush(INVALID_HANDLE_VALUE);DWORD direct_error=GetLastError();
 SetLastError(789);BOOL wrapped=traced_flush(INVALID_HANDLE_VALUE);DWORD wrapped_error=GetLastError();
 if(direct || wrapped || direct_error!=ERROR_INVALID_HANDLE || wrapped_error!=direct_error || flush_count!=1 || !flush_records[0].complete)return 11;
 memset(flush_records,0,sizeof(flush_records));flush_count=0;
 int enabled=!GetEnvironmentVariableW(L"NEXAUI_R01_NO_FLUSH_HOOK",NULL,0);
 if(enabled && !exchange_slot((void *)original_flush,(void *)traced_flush))return 12;
 int result=trace_run(argc,argv);
 int restored=!enabled || exchange_slot((void *)traced_flush,(void *)original_flush);
 for(unsigned i=0;i<1000 && InterlockedCompareExchange(&active_calls,0,0);++i)Sleep(1);
 int count=InterlockedCompareExchange(&flush_count,0,0),incomplete=0;
 fprintf(stderr,"FLUSH {\"enabled\":%d,\"restored\":%d,\"invalid_handle_control\":%lu,\"slot_rva\":%lu,\"count\":%d,\"records\":[",enabled,restored,wrapped_error,slot_rva,count);
 for(int i=0;i<count && i<256;++i){flush_record *r=&flush_records[i];
  if(!r->complete){++incomplete;continue;}
  fprintf(stderr,"%s{\"tid\":%lu,\"begin\":%lld,\"end\":%lld,\"metadata_end\":%lld,\"ms\":%.6f,\"ok\":%d,\"error\":%lu,\"cpu_error\":%lu,\"thread_cpu_ms\":%.6f,\"process_cpu_ms\":%.6f,\"io_error\":%lu,\"io_write_operations\":%llu,\"io_write_bytes\":%llu,\"path_error\":%lu,\"path\":",i?",":"",r->tid,r->begin,r->end,r->metadata_end,ms(r->end-r->begin),r->ok,r->error,r->before.error?r->before.error:r->after.error,(r->after.thread-r->before.thread)/10000.0,(r->after.process-r->before.process)/10000.0,r->io_error,r->io_after.WriteOperationCount-r->io_before.WriteOperationCount,r->io_after.WriteTransferCount-r->io_before.WriteTransferCount,r->path_error);
  json_path(r->path);FILE_STORAGE_INFO s=r->storage;
  fprintf(stderr,",\"storage_error\":%lu,\"logical_sector\":%lu,\"physical_atomicity\":%lu,\"physical_performance\":%lu,\"filesystem_atomicity\":%lu,\"storage_flags\":%lu}",r->storage_error,s.LogicalBytesPerSector,s.PhysicalBytesPerSectorForAtomicity,s.PhysicalBytesPerSectorForPerformance,s.FileSystemEffectivePhysicalBytesPerSectorForAtomicity,s.Flags);
 }
 fprintf(stderr,"],\"incomplete\":%d,\"active\":%ld}\n",incomplete,active_calls);
 FreeLibrary(cache);return result||!restored||incomplete||active_calls||count>256?13:0;
}

