  printf("%s{\"index\":%d,\"file\":%d,\"written\":%lu,\"begin\":%lld,\"end\":%lld,\"flush_ms\":%.6f,\"error\":%lu,\"storage_error\":%lu,\"logical_sector\":%lu,\"physical_atomicity\":%lu,\"filesystem_atomicity\":%lu}",i?",":"",i+1,file,written,begin,end,1000.0*(end-begin)/freq.QuadPart,error,info?0:GetLastError(),storage.LogicalBytesPerSector,storage.PhysicalBytesPerSectorForAtomicity,storage.FileSystemEffectivePhysicalBytesPerSectorForAtomicity);
  if(!result || !info)return 5;
 }
 for(int i=0;i<2;++i){LARGE_INTEGER offset={0};DWORD got=0;memset(data,last[i],sizeof(data));
  if(!SetFilePointerEx(files[i],offset,NULL,FILE_BEGIN) || !ReadFile(files[i],verify,sizeof(verify),&got,NULL) || got!=sizeof(verify) || memcmp(data,verify,sizeof(data)))return 6;
